import{_ as a,o as i,a as t,b as _}from"./app.C41L12d5.js";const I=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"矩阵计算（ISASI）","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_ISASI"},{"text":"矩阵搬出关键特性说明","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_store_key_features/cube_store_key_features"},{"text":"随路relu","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_store_key_features/accompanying_relu"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/cube_compute_ISASI/cube_store_key_features/accompanying_relu.md","filePath":"api/SIMD-API/basic_api/cube_compute_ISASI/cube_store_key_features/accompanying_relu.md","outlineHeaders":[{"level":2,"title":"特性说明","slug":"特性说明","link":"#特性说明"}],"lastUpdated":1785832713000}'),c={name:"api/SIMD-API/basic_api/cube_compute_ISASI/cube_store_key_features/accompanying_relu.md"};function l(p,e,r,o,u,s){return i(),t("div",null,[...e[0]||(e[0]=[_('<div><article class="markdown-body"><h1>随路ReLU<span id="ZH-CN_TOPIC_0000002538231206"></span></h1><h2 id="特性说明">特性说明<a class="header-anchor" href="#特性说明">​</a></h2><p>矩阵计算的搬出过程中支持随路ReLU能力，当前支持如下随路ReLU能力。<strong>DataCopyCO12DstParams结构体参数</strong>定义中reluPre可设置为1开启Normal ReLU，结合clipReluPre可进一步开启ClipReLU能力。</p><ul><li><p>参数配置为0时，即不开启随路ReLU能力。</p></li><li><p>参数配置为1时，即Normal ReLU，无需配置额外寄存器，对输出数据执行激活处理：<code>y = max(0, x)</code>。</p></li><li><p>开启Normal ReLU（reluPre=1）且同时配置clipReluPre=1并调用SetFixPipeClipRelu接口时，即Normal ReLU + ClipReLU，先执行<code>y = max(0, x)</code>，再执行<code>y = min(clipReluMaxVal, y)</code>，其中clipReluMaxVal通过SetFixPipeClipRelu接口设置。详见<a href="../cube_store_aux_config/SetFixPipeClipRelu.html">SetFixPipeClipRelu</a>。</p></li></ul><p>与随路量化组合使用的详细信息请参考<a href="accompanying_quantization_and_relu_scenario_combination.html">随路量化与随路ReLU场景组合</a>。</p></article></div>',1)])])}const m=a(c,[["render",l]]);export{I as __pageData,m as default};
